
const express = require("express");

const app = express();

const port = 3001;

app.use(express.json());

let students = [
    {
        id: 1,
        name: "Damini",
        course: "AI&DS"
    },
    {
        id: 2,
        name: "Anuja",
        course: "AI&DS"
    },
    {
        id: 3,
        name: "Sunita",
        course: "AI&DS"
    }
];

app.get("/students", (req, res) => {
    res.json(students);
});

app.listen(port, () => {
    console.log(`Server running at http://localhost:${port}`);
});

